import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
T="CRISIS DE ASMA"; N=7
note=lambda t: f'<div style="font-size:36px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:22px">'+"".join(x)+'</div>'
P=[
page(1,N,T,big("CRISIS DE ASMA",134,nowrap=True)+big(f'EL INHALADOR CON CÁMARA <span style="color:{R}">VALE</span> LO QUE EL NEBULIZADOR',96)+'<div style="font-size:40px;font-weight:600;line-height:1.3;max-width:820px">Gravedad, dosis y cuándo escalar. Con ficha final para guardar.</div>',cover=True),
page(2,N,T,big("¿CUÁNTO ES GRAVE?",124,nowrap=True)+rows(row("Leve","PEF o FEV1 &gt; 70 %"),row("Moderada","PEF o FEV1 50–70 %"),f'<div style="border-top:4px solid {K};padding-top:22px;display:flex;justify-content:space-between;gap:32px;font-size:40px;color:{R}"><div style="font-weight:800">Grave</div><div style="font-weight:800;text-align:right">PEF o FEV1 &lt; 50 %</div></div>')+f'<div style="border-top:4px solid {K};padding-top:28px;font-size:42px;font-weight:800;line-height:1.3">Riesgo vital: silencio auscultatorio, cianosis, bradicardia, hipotensión o bajo nivel de consciencia</div>'),
page(3,N,T,kicker("PASO 1 · BRONCODILATA")+big("SALBUTAMOL",170,R,True)+rows(row("Inhalador + cámara","4–8 pulsaciones cada 10–15 min"),row("Nebulizado","2,5–5 mg cada 20 min"),row("Durante","La primera hora"))+note("En crisis leves y moderadas, el cartucho presurizado con cámara es tan eficaz como la nebulización.")),
page(4,N,T,kicker("PASO 2 · MODERADA O GRAVE")+big("SUMA IPRATROPIO",124,R,True)+rows(row("Nebulizado","0,5 mg cada 20 min"),row("Inhalador + cámara","4–8 pulsaciones cada 10–15 min"))+f'<div style="border-top:4px solid {K};padding-top:28px;display:flex;flex-direction:column;gap:22px">{big("OXÍGENO",110)}<div style="font-size:46px;font-weight:800;line-height:1.2">Si la saturación es &lt; 92 %, a concentración baja (FiO2 &lt; 40 %)</div></div>'),
page(5,N,T,kicker("PASO 3 · DESINFLAMA")+big("CORTICOIDE PRONTO",118,R,True)+rows(row("Prednisona oral","40–50 mg"),row("Hidrocortisona IV","100–200 mg"),row("Metilprednisolona IV","60–80 mg"))+note("La vía oral es tan eficaz como la intravenosa si el paciente traga. Al alta: prednisona 5–7 días, sin pauta descendente.")),
page(6,N,T,kicker("PASO 4 · SI NO RESPONDE")+big("MAGNESIO IV",160,R,True)+'<div style="font-size:50px;font-weight:800;line-height:1.2">Sulfato de magnesio: 2 g en 20 min, dosis única</div>'+rows(line("Reevalúa PEF y saturación a los 30–60 min de cada paso"),line("Sin mejoría o riesgo vital: avisa a UCI; valora ventilación no invasiva o intubación",True))),
page(7,N,T,ficha_body("CRISIS DE ASMA","Adulto",[("GRAVE","PEF o FEV1 &lt; 50 %, o signos de riesgo vital"),("1. SALBUTAMOL","Inhalador + cámara: 4–8 puls. cada 10–15 min. Nebulizado: 2,5–5 mg cada 20 min (1.ª hora)",True),("2. IPRATROPIO","Moderada o grave: 0,5 mg nebulizado cada 20 min"),("3. CORTICOIDE","Prednisona 40–50 mg oral o hidrocortisona 100–200 mg IV"),("4. SI NO CEDE","Sulfato de magnesio 2 g IV en 20 min"),("OXÍGENO","Si saturación &lt; 92 %. Reevaluar PEF tras cada paso")],"GEMA 5.5 (Guía Española para el Manejo del Asma), apartado de crisis",size=104,fs=32),ficha="05"),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","asma")
